DROP TABLE IF EXISTS `bn_invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bn_invoices` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) unsigned NOT NULL,
  `status` tinyint(2) unsigned NOT NULL,
  `id_furnizor` int(10) unsigned NOT NULL,
  `id_beneficiar` int(10) unsigned NOT NULL,
  `serie` varchar(75) NOT NULL,
  `nr_char` varchar(150) NOT NULL DEFAULT '',
  `date` date NOT NULL,
  `title` varchar(255) NOT NULL,
  `description` varchar(255) NOT NULL,
  `info_furnizor` text NOT NULL,
  `info_beneficiar` text NOT NULL,
  `info_invoice` text NOT NULL,
  `moneda` varchar(3) NOT NULL DEFAULT '',
  `curs_valutar` text NOT NULL,
  `nr` int(10) unsigned NOT NULL,
  `tva` tinyint(2) unsigned NOT NULL,
  `valoare` decimal(10,2) NOT NULL,
  `taxa` decimal(10,2) NOT NULL,
  `valoare_platita` decimal(10,2) NOT NULL,
  `options` int(10) unsigned NOT NULL,
  `id_anexa` int(10) unsigned NOT NULL,
  `id_contract` int(10) unsigned NOT NULL,
  `id_comanda` int(10) unsigned NOT NULL,
  `zile_scadenta` int(11) unsigned NOT NULL,
  `data_scadentei` date NOT NULL,
  `id_parent` int(10) unsigned NOT NULL,
  `id_user` int(10) unsigned NOT NULL,
  `uid` varchar(40) NOT NULL,
  `zile_recurenta` int(10) NOT NULL,
  `voucher` int(11) NOT NULL,
  `awb` varchar(15) NOT NULL,
  `transport` decimal(10,2) NOT NULL,
  `id_livrare` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `type` (`type`),
  KEY `id_furnizor` (`id_furnizor`),
  KEY `id_beneficiar` (`id_beneficiar`),
  KEY `id_anexa` (`id_anexa`),
  KEY `id_contract` (`id_contract`),
  KEY `id_parent` (`id_parent`)
) ENGINE=InnoDB AUTO_INCREMENT=1741 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
