DROP TABLE IF EXISTS `bn_posts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bn_posts` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `master_id` int(10) unsigned NOT NULL,
  `is_category` tinyint(1) unsigned NOT NULL,
  `id_parent` int(10) unsigned NOT NULL,
  `id_template` tinyint(2) unsigned NOT NULL,
  `status` tinyint(2) unsigned NOT NULL,
  `type` varchar(75) NOT NULL DEFAULT '',
  `date_added` date NOT NULL,
  `date_modified` date NOT NULL,
  `view_count` int(11) NOT NULL,
  `view_count_today` int(10) unsigned NOT NULL,
  `file_name` varchar(75) NOT NULL DEFAULT '',
  `files` varchar(255) NOT NULL DEFAULT '',
  `email` varchar(75) NOT NULL DEFAULT '',
  `author` varchar(150) NOT NULL DEFAULT '',
  `telephone` varchar(75) NOT NULL DEFAULT '',
  `lat_lng` varchar(75) NOT NULL DEFAULT '',
  `price` decimal(10,2) NOT NULL,
  `url` varchar(150) NOT NULL DEFAULT '',
  `video_id` varchar(255) NOT NULL DEFAULT '',
  `options` int(10) unsigned NOT NULL,
  `sort_order` int(11) NOT NULL,
  `seo_url` varchar(255) NOT NULL DEFAULT '',
  `ts_published` int(10) unsigned NOT NULL,
  `ts_added` int(10) unsigned NOT NULL,
  `id_admin` int(10) unsigned NOT NULL,
  `fav_category` int(10) unsigned NOT NULL,
  `is_important` tinyint(1) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `master_id` (`master_id`),
  KEY `id_parent` (`id_parent`),
  KEY `is_category` (`is_category`),
  KEY `type` (`type`),
  KEY `status` (`status`),
  KEY `seo_url` (`seo_url`),
  KEY `is_important` (`is_important`),
  KEY `fav_category` (`fav_category`),
  KEY `date_added` (`date_added`),
  KEY `view_count_today` (`view_count_today`)
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

